function* unalignedFanIn<K,V>(sources: Array<Iterable<[K,V]>>, bufferMs: number) {
  const buf: Array<{k:K,v:V,src:number,ts:number}> = [];
  for (let i = 0; i < sources.length; i++) {
    for (const [k,v] of sources[i]) buf.push({k,v,src:i,ts:Date.now()});
    const cutoff = Date.now() - bufferMs;
    while (buf.length && buf[0].ts < cutoff) {
      const head = buf.shift()!;
      const partner = buf.find(x => x.k === head.k && x.src !== head.src);
      if (partner) yield [head.k, head.v, partner.v];
    }
  }
}
